function render(v){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));const e=$(v);if(pages[v]){const[p,h,d,b]=pages[v];e.innerHTML=`<div class="page"><small class="eyebrow">${p}</small><h2>${h}</h2><p class="muted">${d}</p>${b}</div>`}e.classList.add('active');$('crumb').textContent=pages[v]?.[1]||'Beranda';e.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>render(b.dataset.view));window.scrollTo({top:0,behavior:'smooth'})}
function analyze(){const t=$('question').value.trim();if(!t)return;document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));const r=$('result');r.classList.add('active');$('crumb').textContent='Hasil Analisis';r.innerHTML=`<div class="page"><small class="eyebrow">ORCHESTRATOR</small><h2>Menganalisis: “${esc(t)}”</h2><div class="flow"><span>Intent</span><span>Lokasi</span><span>Evidence</span><span>Confidence</span><span>Forecast</span><span>Solution</span></div><div class="card"><span class="live">DEMO ANALYSIS</span><h3>Sinyal utama ditemukan; validasi sumber diperlukan sebelum keputusan produksi.</h3><p class="muted">Alur jawaban: ringkasan → bukti → confidence → ketidakpastian → opsi tindakan.</p></div></div>`;window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('nav [data-view]').forEach(b=>b.onclick=()=>render(b.dataset.view));document.querySelectorAll('.chips [data-q]').forEach(b=>b.onclick=()=>{$('question').value=b.dataset.q;analyze()});$('ask').onclick=analyze;$('question').onkeydown=e=>{if(e.key==='Enter')analyze()};render('home');